using System.Windows;
using System.Windows.Controls;
using System.Windows.Input;

namespace Tune.Components
{
    // Generated by AI.
    public partial class Pause : UserControl
    {
        // ──────── 依赖属性：IsPlaying（只读显示，由外部单向绑定）────────
        public static readonly DependencyProperty IsPlayingProperty =
            DependencyProperty.Register(
                nameof(IsPlaying),
                typeof(bool),
                typeof(Pause),
                new FrameworkPropertyMetadata(false, OnIsPlayingChanged));

        // ──────── 依赖属性：ToggleCommand（点击时执行）────────
        public static readonly DependencyProperty ToggleCommandProperty =
            DependencyProperty.Register(
                nameof(ToggleCommand),
                typeof(ICommand),
                typeof(Pause),
                new PropertyMetadata(null));

        // ──────── .NET 属性包装器 ────────
        public bool IsPlaying
        {
            get => (bool)GetValue(IsPlayingProperty);
            set => SetValue(IsPlayingProperty, value);
        }

        public ICommand ToggleCommand
        {
            get => (ICommand)GetValue(ToggleCommandProperty);
            set => SetValue(ToggleCommandProperty, value);
        }

        // 自定义事件（可选，保留以备他用）
        public event EventHandler? IsPlayingChanged;

        public Pause()
        {
            InitializeComponent();
            this.MouseLeftButtonDown += OnMouseLeftButtonDown;
            UpdateVisualState();
        }

        // ──────── 依赖属性回调 ────────
        private static void OnIsPlayingChanged(DependencyObject d, DependencyPropertyChangedEventArgs e)
        {
            var control = (Pause)d;
            control.OnIsPlayingChanged((bool)e.OldValue, (bool)e.NewValue);
        }

        protected virtual void OnIsPlayingChanged(bool oldValue, bool newValue)
        {
            UpdateVisualState();
            IsPlayingChanged?.Invoke(this, EventArgs.Empty);
        }

        // ──────── 视觉更新 ────────
        private void UpdateVisualState()
        {
            if (this.Content is Grid grid && grid.Children.Count >= 2)
            {
                var pauseImg = grid.Children[0] as Image;
                var playImg = grid.Children[1] as Image;

                if (pauseImg != null && playImg != null)
                {
                    if (IsPlaying)
                    {
                        pauseImg.Visibility = Visibility.Visible;
                        playImg.Visibility = Visibility.Hidden;
                    }
                    else
                    {
                        pauseImg.Visibility = Visibility.Hidden;
                        playImg.Visibility = Visibility.Visible;
                    }
                }
            }
        }

        // ──────── 点击处理 ────────
        private void OnMouseLeftButtonDown(object sender, MouseButtonEventArgs e)
        {
            // 如果绑定了命令，就执行命令；不再直接修改 IsPlaying
            if (ToggleCommand != null && ToggleCommand.CanExecute(null))
            {
                ToggleCommand.Execute(null);
            }
        }
    }
}